Node 24 — built-in WebSocket available. Create a smoke script in the temp directory:

Script outline:
```js
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { spawn } from 'node:child_process';
import { setTimeout as sleep } from 'node:timers/promises';
import path from 'node:path';

const ROOT = 'D:/dev/ab-tasks/chessground-qwen-med-r1';
const MIME = { '.html':'text/html', '.js':'text/javascript', '.css':'text/css', '.json':'application/json', '.png':'image/png', '.jpg':'image/jpeg' };

// 1. Static server
const server = createServer(async (req, res) => {
  const url = new URL(req.url, 'http://x');
  let p = path.join(ROOT, decodeURIComponent(url.pathname));
  try {
    const data = await readFile(p);
    res.writeHead(200, { 'content-type': MIME[path.extname(p)] || 'application/octet-stream' });
    res.end(data);
  } catch {
    res.writeHead(404); res.end('not found: ' + p);
  }
});
await new Promise(r => server.listen(8471, '127.0.0.1', r));

// 2. Launch Chrome
const chrome = spawn('C:/Program Files/Google/Chrome/Application/chrome.exe', [
  '--headless=new', '--no-first-run', '--no-default-browser-check',
  '--disable-gpu', '--remote-debugging-port=9333', '--user-data-dir=' + tmpProfile,
  'about:blank',
], { stdio: 'ignore' });

// Wait for CDP endpoint
let ver;
for (let i = 0; i < 50; i++) {
  try { ver = await (await fetch('http://127.0.0.1:9333/json/version')).json(); break; }
  catch { await sleep(200); }
}
if (!ver) throw new Error('chrome did not start');

// Create a tab targeting demo.html
const tab = await (await fetch('http://127.0.0.1:9333/json/new?http://127.0.0.1:8471/demo.html', { method: 'PUT' })).json();

const ws = new WebSocket(tab.webSocketDebuggerUrl);
await new Promise((r, j) => { ws.onopen = r; ws.onerror = j; });

let id = 0; const pending = new Map(); const events = [];
const errors = [];
ws.onmessage = m => {
  const msg = JSON.parse(m.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  else if (msg.method) {
    events.push(msg.method);
    if (msg.method === 'Runtime.exceptionThrown') errors.push(JSON.stringify(msg.params.exceptionDetails));
    if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') errors.push(msg.params.args.map(a=>a.value??a.description).join(' '));
    if (msg.method === 'Log.entryAdded' && msg.params.entry.level === 'error') errors.push(msg.params.entry.text);
  }
};
const send = (method, params={}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({id:i, method, params})); });
const evalJs = async (expr) => (await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true })).result.result.value;

await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:8471/demo.html' });
// Wait for load
for (let i = 0; i < 100 && !events.includes('Page.loadEventFired'); i++) await sleep(100);

// Assert the board rendered
const boards = await evalJs(`document.querySelectorAll('cg-board').length`);
const squares = await evalJs(`document.querySelectorAll('#board-1 square').length`); // Is square an element? createEl('square')... 
```

Wait — square element: does chessground create `<div class="square">`? Let me check createEl in util.ts: `createEl(name)` — I have a feeling the square's className was something like `square light/dark` on a div. Actually chessground uses a `div` with a square class. Let me not guess; I'll count `.square` inside #board-1.

```js
const before = await evalJs(`(() => { const c = document.querySelector('#board-1 cg-container'); return { w: c.style.width, rect: c.getBoundingClientRect().width }; })()`);
// Resize the wrap
await evalJs(`document.getElementById('board-1').style.width = '300px'; 'ok'`);
await sleep(300); // RO fires
const after = await evalJs(`(() => { const c = document.querySelector('#board-1 cg-container'); const sq = document.querySelector('#board-1 .square'); return { style: c.style.width, rect: c.getBoundingClientRect().width, squareRect: sq ? sq.getBoundingClientRect().width : null }; })()`);
