  const squares = await evalJs(`document.querySelectorAll('#board-1 square').length`);
  check('64 squares in board-1', squares === 64, `got ${squares}`);
  const pieces = await evalJs(`document.querySelectorAll('#board-1 piece').length`);
  check('32 pieces in board-1', pieces === 32, `got ${pieces}`);
  const nOnD5 = await evalJs(`document.querySelector('#board-2 piece.wN') !== null`);
  check('fen board-2 shows white knight on d5', nOnD5 === true);
  check('no page/console errors', pageErrors.length === 0, pageErrors.join(' | '));

  if (squares !== 64) {
